export type ReportKind = "daily" | "weekly" | "monthly";

export type ReportTemplate = {
	/**  Text only (`# ` is added by the app); `{日付}` and `{曜日}` are filled in. */
	title: string,
	/**  Every kind once, 所感・連絡事項 last (see [`ReportTemplate::normalized`]). */
	sections: Section[],
};

/**  A TODO that contains every word. */
export type SearchHit = {
	item: TodoItem,
	/**
	 *  The whole title, with the words marked (no hit when the title has
	 *  none of them).
	 */
	title: Segment[],
	/**
	 *  Memo, 待っている相手, 中止の理由, then up to 3 work logs (newest
	 *  first). Only the fields that contain a word.
	 */
	matches: SearchMatch[],
};

/**  One place a word was found, with the text around it. */
export type SearchMatch = {
	field: MatchField,
	/**  The work log's date (`work_log` only). */
	log_date: string | null,
	/**
	 *  About 30 characters before and after the first hit, line breaks as
	 *  spaces, with 「…」 where the text was cut.
	 */
	segments: Segment[],
};

export type SearchResult = {
	/**  At most 100, title hits first, then the most recently updated. */
	hits: SearchHit[],
	/**  Every TODO that contains every word (may exceed `hits`). */
	total: number,
};

/**  One section: `{ kind, heading, enabled, options }`. */
export type Section = {
	/**  Text only (`## ` is added by the app). */
	heading: string,
	/**  Shown in the report. Always true for 所感・連絡事項. */
	enabled: boolean,
} & SectionBody;

/**  The kind of a section and its options (`"kind"` and `"options"` in JSON). */
export type SectionBody = { kind: "work"; options: WorkOptions } | { kind: "closed"; options: ClosedOptions } | { kind: "waiting"; options: WaitingOptions } | { kind: "tomorrow"; options: TomorrowOptions } | { kind: "attention"; options: AttentionOptions } | { kind: "note"; options: NoteOptions };

/**  A piece of text: one of the words (`hit`) or the text between them. */
export type Segment = {
	text: string,
	hit: boolean,
};

export type Settings = {
	reminder_frequency: ReminderFrequency,
	/**  Days counted as 「間近」. */
	soon_days: number,
	/**  Default follow-up date when moving to 待ち: today + N days. */
	follow_up_days: number,
	/**  Last day the reminder was acknowledged. */
	last_reminded_on: string | null,
	theme: Theme,
	/**  OS notifications at `notify_times` (v1.1). */
	notify_enabled: boolean,
	/**  Notification times, `HH:MM`, 1 to 5, distinct, in time order. */
	notify_times: string[],
	/**
	 *  When the timer last handled a notification time (written by the
	 *  timer, not by update_settings).
	 */
	last_notified_at: string | null,
	/**  × hides the window to the tray instead of quitting. */
	close_to_tray: boolean,
	/**  Start at login (registered with the OS by release builds only). */
	autostart: boolean,
	/**  The tray hint was shown (written by the app, not by update_settings). */
	tray_hint_shown: boolean,
	/**  暦日 or 営業日 (v1.1). */
	day_count: DayCount,
	/**  The user's own holidays (v1.1). */
	custom_holidays: CustomHoliday[],
	/**  Sections, headings and items of the daily report (v1.1). */
	report_template: ReportTemplate,
};

/**
 *  Settings the user edits on the settings screen. `last_reminded_on`,
 *  `last_notified_at` and `tray_hint_shown` are written by the app, not here.
 */
export type SettingsInput = {
	reminder_frequency: ReminderFrequency,
	soon_days: number,
	follow_up_days: number,
	theme: Theme,
	notify_enabled: boolean,
	/**  `HH:MM`, 1 to 5, distinct (saved in time order). */
	notify_times: string[],
	close_to_tray: boolean,
	autostart: boolean,
	day_count: DayCount,
	/**  Names 1 to 30 characters, `start <= end`, at most 31 days each. */
	custom_holidays: CustomHoliday[],
	/**
	 *  Title 1 to 60 characters; headings 1 to 40 characters, all different.
	 *  Saved normalized (see `ReportTemplate::checked`).
	 */
	report_template: ReportTemplate,
};

/**  What the startup reminder dialog shows. */
export type StartupReminder = {
	today: string,
	frequency: ReminderFrequency,
	/**  日限注意 in display order (never empty). */
	items: TodoItem[],
};

/**  TODO status (`todos.status`). The stored value is [`Status::as_str`]. */
export type Status = 
/**  未着手 */
"todo" | 
/**  作業中 */
"doing" | 
/**  待ち */
"waiting" | 
/**  保留 */
"hold" | 
/**  完了 */
"done" | 
/**  中止 */
"cancelled";

/**  A requested status change, with the extra input some targets need. */
export type StatusChange = {
	to: Status,
	/**  Required when moving to 待ち. */
	waiting_on: string | null,
	/**  Required when moving to 待ち. */
	follow_up_date: string | null,
	/**  Required when moving to 中止. */
	reason: string | null,
};

/**  Number of TODOs per status. */
export type StatusCounts = {
	todo: number,
	doing: number,
	waiting: number,
	hold: number,
	done: number,
	cancelled: number,
};

/**
 *  A template as the screens list it (list_todo_templates): what the
 *  「TODOを追加」 dialog fills in and shows, and the settings card's list.
 */
export type TemplateSummary = {
	id: number,
	name: string,
	/**  The parent's title (the dialog puts it in the title field). */
	title: string,
	priority: Priority,
	/**  The children's titles, in the template's order. */
	child_titles: string[],
	updated_at: string,
};

/**  Colour scheme. */
export type Theme = 
/**  ライト (default; selected in the settings mock) */
"light" | 
/**  ダーク */
"dark" | 
/**  OSの設定に合わせる */
"system";

/**  One line of the detail panel's timeline: a work log or a recorded change. */
export type TimelineEntry = { type: "work_log"; entry: WorkLog } | { type: "event"; entry: EventEntry };

export type Todo = {
	id: number,
	project_id: number,
	/**
	 *  The parent, for a child (サブTODO, v0.3.0). One level only, same
	 *  project (checked by the app: `domain::subtodo`).
	 */
	parent_id: number | null,
	title: string,
	status: Status,
	priority: Priority,
	/**  日限 */
	due_date: string | null,
	planned_start: string | null,
	planned_end: string | null,
	actual_start: string | null,
	actual_end: string | null,
	/**  待ち: who / what we are waiting on. */
	waiting_on: string | null,
	/**  待ち: the day waiting started (set automatically). */
	waiting_since: string | null,
	/**  待ち: next day to check (確認日). */
	follow_up_date: string | null,
	/**  When the TODO was completed or cancelled. */
	closed_at: string | null,
	/**  中止の理由 */
	close_reason: string | null,
	memo_md: string,
	sort_order: number,
	created_at: string,
	updated_at: string,
};

/**  A stored event. */
export type TodoEvent = {
	id: number,
	todo_id: number,
	event_date: string,
	kind: EventKind,
	old_value: string | null,
	new_value: string | null,
	note: EventNote,
	occurred_at: string,
};

/**
 *  Every editable field of a TODO (the detail panel sends them all). The
 *  status and the automatic fields change only through `change_status`.
 */
export type TodoFields = {
	title: string,
	priority: Priority,
	due_date: string | null,
	planned_start: string | null,
	planned_end: string | null,
	actual_start: string | null,
	actual_end: string | null,
	/**  Used only while 待ち (required then); ignored otherwise. */
	waiting_on: string | null,
	/**  Used only while 待ち (required then); ignored otherwise. */
	follow_up_date: string | null,
	/**  Used only while 中止 (required then); ignored otherwise. */
	close_reason: string | null,
	memo_md: string,
};

/**  A TODO as shown in lists and the detail panel. */
export type TodoItem = {
	todo: Todo,
	project_name: string,
	assessment: Assessment,
	/**
	 *  Statuses `change_status` accepts from the current one (the status
	 *  select offers only these).
	 */
	next_statuses: Status[],
	/**
	 *  The follow-up date offered when this TODO goes 待ち today: the
	 *  setting's days (business days in 営業日) after today.
	 */
	follow_up_default: string,
	/**  The parent's title, for a child (S-1). Shown as 「親 / 子」. */
	parent_title: string | null,
	/**  The children counts, for a TODO with children (S-1). */
	children: ChildCounts | null,
	/**  An open child due after its parent (「親の日限より後」). */
	due_after_parent: boolean,
	/**
	 *  Its repetition (T-12), with the next round's 日限 if it were closed
	 *  today. `null` = it does not repeat.
	 */
	repeat: RepeatInfo | null,
	/**
	 *  The unfinished TODOs it waits for (T-11): the list's mark and the
	 *  confirmation before 作業中. Empty when closed.
	 */
	blocked_by: BlockingTodo[],
	/**
	 *  Open, and planned to start before an unfinished TODO it waits for is
	 *  planned to end (「先のTODOより前に始まる予定」, T-11).
	 */
	starts_before_dependency: boolean,
};

/**
 *  The TODO list with the counts for its status tabs. The counts cover the
 *  project, 日限 and 優先度 filters but not the status filter, so every tab
 *  shows how many rows it would list (bridge rows are not counted).
 */
export type TodoList = {
	rows: TodoListRow[],
	counts: StatusCounts,
	/**  The 「すべて」 tab. */
	total: number,
};

/**  A row of the TODO list, in tree order (S-1): a parent, then its children. */
export type TodoListRow = {
	item: TodoItem,
	/**  Shown indented under its parent. */
	child: boolean,
	/**
	 *  A parent that does not match the filters, shown (dimmed) only to
	 *  hold its matching children. Not counted in the tabs.
	 */
	bridge: boolean,
};

export type TodoQuery = {
	/**
	 *  Only this project (its TODOs are listed even when it is archived).
	 *  `null` = all active projects.
	 */
	project_id: number | null,
	/**  Only these statuses. `null` = all. */
	statuses: Status[] | null,
	/**  Only this priority. `null` = all. */
	priority: Priority | null,
	/**  日限 filter. `null` = all. */
	due: DueFilter | null,
	/**  `null` = 登録順. */
	sort: TodoSort | null,
};

/**  Order of the list. */
export type TodoSort = 
/**  登録順: project order, then the order TODOs were added. */
"manual" | 
/**  日限の近い順 (no due date last), then priority. */
"due_date" | 
/**  優先度の高い順, then due date. */
"priority";

/**  明日の予定. */
export type TomorrowOptions = {
	/**  「(予定 11/20〜11/27)」 of 未着手. */
	planned_period: boolean,
};

/**
 *  Urgency category. Declared in severity order (most severe first), so the
 *  derived `Ord` sorts 超過 → 本日 → 間近 → 要確認 → 着手遅れ.
 */
export type Urgency = 
/**  超過: due date is before today. */
"overdue" | 
/**  本日: due date is today. */
"due_today" | 
/**  間近: due date is between tomorrow and `soon_days` days from today. */
"due_soon" | 
/**  要確認: waiting, and the follow-up date is today or earlier. */
"follow_up" | 
/**  着手遅れ: not started, and the planned start is before today. */
"late_start";

/**  Number of TODOs in each 日限注意 category. */
export type UrgencyCounts = {
	overdue: number,
	due_today: number,
	due_soon: number,
	follow_up: number,
	late_start: number,
};

/**  待ち. */
export type WaitingOptions = {
	/**  「人事部の原稿確認待ち」 */
	waiting_on: boolean,
	/**  「3日目」 */
	waiting_days: boolean,
	/**  「確認日 11/19」 */
	follow_up_date: boolean,
};

/**  The two small warning icons shown in the list and the Gantt chart. */
export type Warnings = {
	/**  計画が間に合わない: planned end is after the due date. */
	plan_misses_due: boolean,
	/**  予定超過: doing or waiting, and the planned end is before today. */
	plan_overrun: boolean,
};

export type WorkLog = {
	id: number,
	todo_id: number,
	log_date: string,
	body_md: string,
	minutes: number | null,
	created_at: string,
	updated_at: string,
};

export type WorkLogInput = {
	/**  `null` adds a new log; otherwise updates that log. */
	id: number | null,
	todo_id: number,
	log_date: string,
	body_md: string,
	/**  作業時間 in minutes (optional). */
	minutes: number | null,
};

/**  本日の作業. */
export type WorkOptions = {
	/**
	 *  「### プロジェクト名」 above each project's TODOs. Off: each line
	 *  starts with 「プロジェクト名 / 」.
	 */
	project_headings: boolean,
	/**  「(作業中 …)」 */
	status: boolean,
	/**  「… / 日限 11/20」 (open TODOs only). */
	due_date: boolean,
	/**  「1.5h」 */
	work_time: boolean,
};
